INSERT INTO "reviews" ("id", "business_id", "business_name", "user_name", "user_email", "rating", "title", "body", "is_verified", "helpful_count", "created_at") VALUES (1, 1, 'Kesar Da Dhaba', 'Harpreet Singh Sandhu', 'harpreet.sandhu@gmail.com', 5, 'Unmatched Dal Makhani in the heart of Amritsar', 'Visited with family during our Golden Temple trip. The slow-simmered dal cooked in ghee for 24 hours has no equal. Absolutely authentic atmosphere!', 1, 38, '2026-10-20 13:08:12');
INSERT INTO "reviews" ("id", "business_id", "business_name", "user_name", "user_email", "rating", "title", "body", "is_verified", "helpful_count", "created_at") VALUES (2, 2, 'Wenger''s Deli & Bakery', 'Ananya Sharma', 'ananya.s@outlook.com', 5, 'Best shammi kebabs and chocolate mousse in Delhi', 'My grandfather used to buy bread here, and 50 years later the quality has not dropped one bit. The mutton puff is flaky perfection.', 1, 24, '2026-10-20 13:08:12');
INSERT INTO "reviews" ("id", "business_id", "business_name", "user_name", "user_email", "rating", "title", "body", "is_verified", "helpful_count", "created_at") VALUES (3, 4, 'Blue Tokai Coffee Roasters', 'Rohit Malhotra', 'rohit.m@zomato.in', 5, 'Perfect remote work spot with artisanal coffee', 'Excellent flat white made with Attikan Estate beans. The seating is comfortable, WiFi is ultra fast, and staff knows their coffee notes.', 1, 19, '2026-10-20 13:08:12');
INSERT INTO "reviews" ("id", "business_id", "business_name", "user_name", "user_email", "rating", "title", "body", "is_verified", "helpful_count", "created_at") VALUES (4, 5, 'Bosch Car Service Ludhiana', 'Jaswinder Grewal', 'jassi.grewal@yahoo.com', 5, 'Transparent diagnosis, no unnecessary parts billed', 'Had an electrical issue in my Hyundai Creta that two local garages failed to fix. Bosch engineers diagnosed a faulty sensor in 20 minutes.', 1, 15, '2026-10-20 13:08:12');
INSERT INTO "reviews" ("id", "business_id", "business_name", "user_name", "user_email", "rating", "title", "body", "is_verified", "helpful_count", "created_at") VALUES (5, 6, 'Apollo White Dental Clinic', 'Dr. Meera Nambiar', 'meera.nambiar@aiims.edu', 5, 'Painless root canal treatment', 'Top tier hygiene and modern imaging machines. Dr. Priya explained every step on the monitor before beginning.', 1, 12, '2026-10-20 13:08:12');
INSERT INTO "reviews" ("id", "business_id", "business_name", "user_name", "user_email", "rating", "title", "body", "is_verified", "helpful_count", "created_at") VALUES (6, 9, 'Kayani Bakery', 'Firoze Batliwala', 'firoze.b@gmail.com', 5, 'The real Shrewsbury biscuits of Pune', 'Queue starts at 7 AM for a reason! Nothing beats their freshly packed warm biscuits with afternoon tea.', 1, 45, '2026-10-20 13:08:12');
